import { createHash, hkdfSync, randomBytes } from 'node:crypto';

export type TokenRole = 'client' | 'worker';

/** The name inside a token: who holds it, shown to the admin. */
export const TOKEN_NAME = /^[a-z0-9]{1,24}$/;
const TOKEN = /^fornax-([a-z0-9]{1,24})-([A-Za-z0-9_-]{43})$/;

/** A new random token: fornax-<name>-<256 bits as base64url>. Generated by its holder, never by the server. */
export function generateToken(name: string): string {
  if (!TOKEN_NAME.test(name)) throw new Error('token name must be 1-24 characters a-z or 0-9');
  return `fornax-${name}-${randomBytes(32).toString('base64url')}`;
}

export function parseToken(token: string): { name: string } | null {
  const m = TOKEN.exec(token);
  return m ? { name: m[1]! } : null;
}

/** The only form in which the server stores a token. */
export const tokenHash = (token: string): string => createHash('sha256').update(token).digest('hex');

const BASE32 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';

/** First 40 bits of SHA-256 as 8 base32 characters, XXXX-XXXX: compared by people before approval. */
export function fingerprint(token: string): string {
  const bytes = createHash('sha256').update(token).digest().subarray(0, 5);
  let bits = 0n;
  for (const b of bytes) bits = (bits << 8n) | BigInt(b);
  let out = '';
  for (let i = 7; i >= 0; i--) out += BASE32[Number((bits >> BigInt(i * 5)) & 31n)];
  return `${out.slice(0, 4)}-${out.slice(4)}`;
}

/** HMAC key for webhooks: the client derives it from its own token, so no second secret is handed out. */
export function webhookKey(token: string): Buffer {
  return Buffer.from(hkdfSync('sha256', token, Buffer.alloc(0), 'fornax-webhook', 32));
}
